// src/openai/tools.ts
var TOOLS = [
  {
    name: "openai_quick_query",
    description: "Fast, cheap one-shot query to a small OpenAI model. Use for short factual lookups, quick rewrites, format conversions, classifications. Not for multi-step reasoning.",
    inputSchema: {
      type: "object",
      properties: { prompt: { type: "string", description: "The question or task." } },
      required: ["prompt"],
      additionalProperties: false
    }
  },
  {
    name: "openai_reasoning_query",
    description: "Deep-reasoning query to a frontier OpenAI reasoning model. Use for architecture questions, hard bugs, debugging, step-by-step thinking. Slower and more expensive.",
    inputSchema: {
      type: "object",
      properties: { prompt: { type: "string", description: "The problem to reason about." } },
      required: ["prompt"],
      additionalProperties: false
    }
  },
  {
    name: "openai_agent_run",
    description: "Hand an end-to-end task to an autonomous OpenAI agent. Use for tasks you'd rather delegate entirely. More expensive than a query \u2014 reserve for work that needs real autonomy.",
    inputSchema: {
      type: "object",
      properties: { task: { type: "string", description: "A complete task description." } },
      required: ["task"],
      additionalProperties: false
    }
  }
];
function makeHandlers(deps) {
  const runAgent2 = deps?.runAgent ?? runAgent;
  const buildQuick = deps?.buildQuickAgent ?? buildQuickAgent;
  const buildReasoning = deps?.buildReasoningAgent ?? buildReasoningAgent;
  const buildGeneralist = deps?.buildGeneralistAgent ?? buildGeneralistAgent;
  async function viaAgent(agent, input) {
    try {
      const [text, usage] = await runAgent2(agent, input);
      return JSON.stringify(ok(text, { provider: "openai", model: agent.model, usage }));
    } catch (err) {
      return JSON.stringify(classify("openai", err).toToolResponse());
    }
  }
  async function viaAgentWithFallback(primaryAgent, input, buildFb) {
    try {
      const [text, usage] = await runAgent2(primaryAgent, input);
      return JSON.stringify(ok(text, { provider: "openai", model: primaryAgent.model, usage }));
    } catch (err) {
      const pe = classify("openai", err);
      if (pe.kind !== "rate_limit" && pe.kind !== "insufficient_quota") {
        return JSON.stringify(pe.toToolResponse());
      }
      const fb = buildFb();
      if (!fb || fb.model === primaryAgent.model) {
        return JSON.stringify(pe.toToolResponse());
      }
      try {
        const [text, usage] = await runAgent2(fb, input);
        return JSON.stringify(
          ok(text, {
            provider: "openai",
            model: fb.model,
            usage: { ...usage, fallback_from: primaryAgent.model }
          })
        );
      } catch (err2) {
        return JSON.stringify(classify("openai", err2).toToolResponse());
      }
    }
  }
  return {
    openai_quick_query: (args) => viaAgent(buildQuick(), args.prompt),
    openai_reasoning_query: (args) => viaAgentWithFallback(buildReasoning(), args.prompt, () => buildReasoning(reasoningFallbackModel())),
    openai_agent_run: (args) => viaAgentWithFallback(buildGeneralist(), args.task, () => buildGeneralist(reasoningFallbackModel()))
  };
}

