var VERSION2 = true ? "2.1.1" : "0.0.0-dev";

// src/openai/index.ts
appendStartupHeartbeat("openai");
requireEnv("OPENAI_API_KEY", "Get one from https://platform.openai.com/api-keys and set it.");
